package net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProvider;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueobject.PublicKeyVO;

class PublicKeyValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of public key of tenant login provider")
  void test_public_key_value_holder_assign_plain_value() {
    Object holder = new Object();
    PublicKeyValueHolder<Object> value = new PublicKeyValueHolder<>(holder);
    Assertions.assertSame(holder, value.publicKey("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getPublicKeyValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getPublicKey().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.publicKeyNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getPublicKeyValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getPublicKey().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of public key of tenant login provider")
  void test_public_key_value_holder_assign_value_object() {
    Object holder = new Object();
    PublicKeyValueHolder<Object> value = new PublicKeyValueHolder<>(holder);
    PublicKeyVO vo = PublicKeyVO.from("one");
    Assertions.assertFalse(value.getPublicKeyValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.publicKey(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getPublicKeyValue().orElseThrow());
    Assertions.assertSame(holder, value.publicKey(Optional.empty()));
    Assertions.assertFalse(value.getPublicKeyValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.publicKey(Optional.of(vo)));
    Assertions.assertSame(vo, value.getPublicKeyValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of public key of tenant login provider against the original")
  void test_public_key_value_holder_read() {
    Object holder = new Object();
    PublicKeyValueHolder<Object> value = new PublicKeyValueHolder<>(holder);
    PublicKeyVO vo = PublicKeyVO.from("one");
    PublicKeyVO other = PublicKeyVO.from("one");
    TenantLoginProvider original = Mockito.mock(TenantLoginProvider.class);
    Mockito.when(original.getPublicKeyValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readPublicKey(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readPublicKey(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.publicKey(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readPublicKey(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readPublicKey(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of public key of tenant login provider")
  void test_public_key_value_holder_unset() {
    Object holder = new Object();
    PublicKeyValueHolder<Object> value = new PublicKeyValueHolder<>(holder);
    PublicKeyVO vo = PublicKeyVO.from("one");
    value.publicKey(vo);
    Assertions.assertSame(holder, value.unsetPublicKeyIfMatches("publicKey_other"));
    Assertions.assertTrue(value.getPublicKeyValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetPublicKeyIfMatches("publicKey"));
    Assertions.assertFalse(value.getPublicKeyValue().isPresent(),
        "The field name must clear the value");
    value.publicKey(vo);
    Assertions.assertSame(holder, value.unsetPublicKey());
    Assertions.assertFalse(value.getPublicKeyValue().isPresent(), "Unset must clear the value");
  }
}
